import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledBrandsContainer = styled.div({
  width: '100%',
  display: 'grid',
  gridTemplateColumns: 'repeat(4, 1fr)',
  gap: theme.spacing['4'],
});

export const StyleBrandTooltipContainer = styled.div({
  background: '#141414',
  color: '#ffffff',
  padding: '0 8px',
  borderRadius: theme.borderRadius['2'],
  fontSize: theme.fonts.fontSizes['1'],
  fontFamily: theme.fonts.paragraph,
});

export const StyledBrandsItem = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  gap: theme.spacing['1'],
  position: 'relative',
});

interface StyledBrandsImgProps {
  $country?: boolean;
}

export const StyledBrandsImg = styled.img<StyledBrandsImgProps>(
  ({ $country }) => ({
    width: '48px',
    height: '48px',
    borderRadius: '50%',
    border: '1px solid #1414141F',
    ...($country && {
      position: 'absolute',
      width: '16px',
      height: '16px',
      right: '50%',
      transform: 'translateX(28px)',
    }),
  }),
);

type BrandVariation = 'up' | 'down';

interface StyledBrandsVariationProps {
  $variation?: BrandVariation;
}

export const StyledBrandsVariation = styled.p<StyledBrandsVariationProps>(
  ({ $variation }) => ({
    fontSize: theme.fonts.fontSizes['1'],
    lineHeight: theme.fonts.lineHeights['3'],
    color: theme.colors.interfaceLabelPrimary,
    margin: 0,
    ...($variation === 'up' && { color: theme.colors.green.high }),
    ...($variation === 'down' && { color: theme.colors.red.high }),
  }),
);
